     1→import { DataTypes } from 'sequelize';
     2→import sequelize from '../../config/sequelize.js';
     3→
     4→/**
     5→ * PhoneLineUserAssignment Model (Sequelize ORM)
     6→ *
     7→ * Many-to-many relationship between phone lines and agent users.
     8→ * Controls which agents can access conversations from which phone lines.
     9→ *
    10→ * @property {number} id - Primary key
    11→ * @property {number} user_id - Foreign key to users table (agent)
    12→ * @property {number} phone_line_id - Foreign key to phone_lines table
    13→ * @property {Date} assigned_at - Assignment timestamp
    14→ */
    15→const PhoneLineUserAssignment = sequelize.define('PhoneLineUserAssignment', {
    16→  id: {
    17→    type: DataTypes.INTEGER,
    18→    primaryKey: true,
    19→    autoIncrement: true,
    20→  },
    21→  user_id: {
    22→    type: DataTypes.INTEGER,
    23→    allowNull: false,
    24→    references: {
    25→      model: 'users',
    26→      key: 'id',
    27→    },
    28→    validate: {
    29→      notNull: {
    30→        msg: 'User ID is required',
    31→      },
    32→      async isAgent(value) {
    33→        const { default: User } = await import('./User.js');
    34→        const user = await User.findByPk(value, {
    35→          include: [{ association: 'role' }],
    36→        });
    37→        if (!user) {
    38→          throw new Error('User not found');
    39→        }
    40→        if (user.role.role_name !== 'agent' && user.role.role_name !== 'admin') {
    41→          throw new Error('Only agents and admins can be assigned to phone lines');
    42→        }
    43→        if (!user.is_active) {
    44→          throw new Error('Cannot assign inactive user to phone line');
    45→        }
    46→      },
    47→    },
    48→  },
    49→  phone_line_id: {
    50→    type: DataTypes.INTEGER,
    51→    allowNull: false,
    52→    references: {
    53→      model: 'phone_lines',
    54→      key: 'id',
    55→    },
    56→    validate: {
    57→      notNull: {
    58→        msg: 'Phone Line ID is required',
    59→      },
    60→      async isActiveLine(value) {
    61→        const { default: PhoneLine } = await import('./PhoneLine.js');
    62→        const line = await PhoneLine.findByPk(value);
    63→        if (!line) {
    64→          throw new Error('Phone line not found');
    65→        }
    66→        if (!line.is_active) {
    67→          throw new Error('Cannot assign users to inactive phone line');
    68→        }
    69→      },
    70→    },
    71→  },
    72→  assigned_at: {
    73→    type: DataTypes.DATE,
    74→    allowNull: false,
    75→    defaultValue: DataTypes.NOW,
    76→  },
    77→}, {
    78→  tableName: 'phone_line_user_assignments',
    79→  timestamps: false, // This table doesn't have created_at/updated_at, only assigned_at
    80→  underscored: true,
    81→  indexes: [
    82→    {
    83→      name: 'idx_phone_line_user_unique',
    84→      unique: true,
    85→      fields: ['user_id', 'phone_line_id'],
    86→    },
    87→    {
    88→      name: 'idx_phone_line_assignments_user',
    89→      fields: ['user_id'],
    90→    },
    91→    {
    92→      name: 'idx_phone_line_assignments_line',
    93→      fields: ['phone_line_id'],
    94→    },
    95→  ],
    96→});
    97→
    98→/**
    99→ * Static method: Check if user has access to phone line
   100→ */
   101→PhoneLineUserAssignment.hasAccess = async function (userId, phoneLineId) {
   102→  const assignment = await this.findOne({
   103→    where: {
   104→      user_id: userId,
   105→      phone_line_id: phoneLineId,
   106→    },
   107→  });
   108→  return !!assignment;
   109→};
   110→
   111→/**
   112→ * Static method: Get all phone line IDs for a user
   113→ */
   114→PhoneLineUserAssignment.getPhoneLineIdsForUser = async function (userId) {
   115→  const assignments = await this.findAll({
   116→    where: { user_id: userId },
   117→    attributes: ['phone_line_id'],
   118→  });
   119→  return assignments.map((a) => a.phone_line_id);
   120→};
   121→
   122→/**
   123→ * Static method: Get all user IDs for a phone line
   124→ */
   125→PhoneLineUserAssignment.getUserIdsForPhoneLine = async function (phoneLineId) {
   126→  const assignments = await this.findAll({
   127→    where: { phone_line_id: phoneLineId },
   128→    attributes: ['user_id'],
   129→  });
   130→  return assignments.map((a) => a.user_id);
   131→};
   132→
   133→export default PhoneLineUserAssignment;
   134→

