     4→/**
     5→ * LineUserAssignment Model (Sequelize ORM)
     6→ *
     7→ * Many-to-many relationship between WhatsApp lines and users (agents/admins).
     8→ * Controls which agents can access conversations from which lines.
     9→ *
    10→ * @property {number} id - Primary key
    11→ * @property {number} user_id - Foreign key to users table (agent/admin)
    12→ * @property {number} line_id - Foreign key to whatsapp_lines table
    13→ * @property {Date} assigned_at - Assignment timestamp
    14→ */
    15→const LineUserAssignment = sequelize.define('LineUserAssignment', {
    16→  id: {
    17→    type: DataTypes.INTEGER,
    18→    primaryKey: true,
    19→    autoIncrement: true,
    20→  },
    21→  user_id: {
    22→    type: DataTypes.INTEGER,
    23→    allowNull: false,
    24→    references: {
    25→      model: 'users',
    26→      key: 'id',
    27→    },
    28→    validate: {
    29→      notNull: {
    30→        msg: 'User ID is required',
    31→      },
    32→      async isAgent(value) {
    33→        const { default: User } = await import('./User.js');
    34→        const user = await User.findByPk(value, {
    35→          include: [{ association: 'role' }],
    36→        });
    37→        if (!user) {
    38→          throw new Error('User not found');
    39→        }
    40→        const allowedRoles = ['agent', 'admin'];
    41→        if (!allowedRoles.includes(user.role.role_name)) {
    42→          throw new Error('Only agents and admins can be assigned to lines');
    43→        }
    44→        if (!user.is_active) {
    45→          throw new Error('Cannot assign inactive user to line');
    46→        }
    47→      },
    48→    },
    49→  },
    50→  line_id: {
    51→    type: DataTypes.INTEGER,
    52→    allowNull: false,
    53→    references: {
    54→      model: 'whatsapp_lines',
    55→      key: 'id',
    56→    },
    57→    validate: {
    58→      notNull: {
    59→        msg: 'Line ID is required',
    60→      },
    61→      async isActiveLine(value) {
    62→        const { default: WhatsAppLine } = await import('./WhatsAppLine.js');
    63→        const line = await WhatsAppLine.findByPk(value);
    64→        if (!line) {
    65→          throw new Error('WhatsApp line not found');
    66→        }
    67→        if (!line.is_active) {
    68→          throw new Error('Cannot assign users to inactive line');
    69→        }
    70→      },
    71→    },
    72→  },
    73→  assigned_at: {
    74→    type: DataTypes.DATE,
    75→    allowNull: false,
    76→    defaultValue: DataTypes.NOW,
    77→  },
    78→}, {
    79→  tableName: 'line_user_assignments',
    80→  timestamps: false, // This table doesn't have created_at/updated_at, only assigned_at
    81→  underscored: true,
    82→  indexes: [
    83→    {
    84→      name: 'idx_line_user_unique',
    85→      unique: true,
    86→      fields: ['user_id', 'line_id'],
    87→    },
    88→    {
    89→      name: 'idx_assignments_user',
    90→      fields: ['user_id'],
    91→    },
    92→    {
    93→      name: 'idx_assignments_line',
    94→      fields: ['line_id'],
    95→    },
    96→  ],
    97→});
    98→
    99→/**
   100→ * Static method: Check if user has access to line
   101→ */
   102→LineUserAssignment.hasAccess = async function (userId, lineId) {
   103→  const assignment = await this.findOne({
   104→    where: {
   105→      user_id: userId,
   106→      line_id: lineId,
   107→    },
   108→  });
   109→  return !!assignment;
   110→};
   111→
   112→/**
   113→ * Static method: Get all line IDs for a user
   114→ */
   115→LineUserAssignment.getLineIdsForUser = async function (userId) {
   116→  const assignments = await this.findAll({
   117→    where: { user_id: userId },
   118→    attributes: ['line_id'],
   119→  });
   120→  return assignments.map((a) => a.line_id);
   121→};
   122→
   123→/**
   124→ * Static method: Get all user IDs for a line
   125→ */
   126→LineUserAssignment.getUserIdsForLine = async function (lineId) {
   127→  const assignments = await this.findAll({
   128→    where: { line_id: lineId },
   129→    attributes: ['user_id'],
   130→  });
   131→  return assignments.map((a) => a.user_id);
   132→};
   133→
   134→export default LineUserAssignment;
   135→

