     4→/**
     5→ * PhoneLine Model (Sequelize ORM)
     6→ *
     7→ * Represents WhatsApp phone lines associated with a WhatsApp Business Account (WABA).
     8→ * Each phone line has its own configuration and Meta API credentials.
     9→ *
    10→ * @property {number} id - Primary key
    11→ * @property {string} waba_id - WhatsApp Business Account ID
    12→ * @property {string} name - Display name for this phone line
    13→ * @property {string} phone_number - Phone number (E.164 format)
    14→ * @property {string} phone_number_id - Meta Phone Number ID (required for API calls)
    15→ * @property {string} display_phone_number - Formatted phone number for display
    16→ * @property {string} verified_name - Verified business name in Meta
    17→ * @property {string} quality_rating - Quality rating (GREEN, YELLOW, RED, UNKNOWN)
    18→ * @property {string} messaging_limit_tier - Messaging limit tier (TIER_50, TIER_250, etc)
    19→ * @property {boolean} welcome_message_enabled - Enable welcome message
    20→ * @property {string} welcome_message - Welcome message text
    21→ * @property {boolean} auto_reply_enabled - Enable automatic replies
    22→ * @property {string} auto_reply_message - Auto-reply message text
    23→ * @property {object} business_hours - Business hours configuration (JSON)
    24→ * @property {string} out_of_hours_message - Message shown outside business hours
    25→ * @property {boolean} auto_assignment_enabled - Enable automatic conversation assignment
    26→ * @property {number} max_conversations_per_agent - Maximum conversations per agent
    27→ * @property {object} metadata - Additional configuration data (JSON)
    28→ * @property {boolean} is_active - Phone line active status
    29→ * @property {Date} created_at - Auto-managed timestamp
    30→ * @property {Date} updated_at - Auto-managed timestamp
    31→ */
    32→const PhoneLine = sequelize.define('PhoneLine', {
    33→  id: {
    34→    type: DataTypes.INTEGER,
    35→    primaryKey: true,
    36→    autoIncrement: true,
    37→  },
    38→  waba_id: {
    39→    type: DataTypes.STRING(100),
    40→    allowNull: false,
    41→    validate: {
    42→      notNull: {
    43→        msg: 'WABA ID is required',
    44→      },
    45→      notEmpty: {
    46→        msg: 'WABA ID cannot be empty',
    47→      },
    48→    },
    49→  },
    50→  name: {
    51→    type: DataTypes.STRING(100),
    52→    allowNull: false,
    53→    validate: {
    54→      notNull: {
    55→        msg: 'Phone line name is required',
    56→      },
    57→      notEmpty: {
    58→        msg: 'Phone line name cannot be empty',
    59→      },
    60→      len: {
    61→        args: [2, 100],
    62→        msg: 'Phone line name must be between 2 and 100 characters',
    63→      },
    64→    },
    65→  },
    66→  phone_number: {
    67→    type: DataTypes.STRING(20),
    68→    allowNull: false,
    69→    unique: {
    70→      msg: 'Phone number already registered',
    71→    },
    72→    validate: {
    73→      notNull: {
    74→        msg: 'Phone number is required',
    75→      },
    76→      notEmpty: {
    77→        msg: 'Phone number cannot be empty',
    78→      },
    79→      is: {
    80→        args: /^\+?[1-9]\d{1,14}$/,
    81→        msg: 'Phone number must be in E.164 format (e.g., +1234567890)',
    82→      },
    83→    },
    84→  },
    85→  phone_number_id: {
    86→    type: DataTypes.STRING(100),
    87→    allowNull: false,
    88→    validate: {
    89→      notNull: {
    90→        msg: 'Phone Number ID is required',
    91→      },
    92→      notEmpty: {
    93→        msg: 'Phone Number ID cannot be empty',
    94→      },
    95→    },
    96→  },
    97→  display_phone_number: {
    98→    type: DataTypes.STRING(30),
    99→    allowNull: true,
   100→    validate: {
   101→      len: {
   102→        args: [0, 30],
   103→        msg: 'Display phone number must be less than 30 characters',
   104→      },
   105→    },
   106→  },
   107→  verified_name: {
   108→    type: DataTypes.STRING(100),
   109→    allowNull: true,
   110→    validate: {
   111→      len: {
   112→        args: [0, 100],
   113→        msg: 'Verified name must be less than 100 characters',
   114→      },
   115→    },
   116→  },
   117→  quality_rating: {
   118→    type: DataTypes.ENUM('GREEN', 'YELLOW', 'RED', 'UNKNOWN'),
   119→    allowNull: true,
   120→    defaultValue: 'UNKNOWN',
   121→  },
   122→  messaging_limit_tier: {
   123→    type: DataTypes.STRING(50),
   124→    allowNull: true,
   125→    validate: {
   126→      len: {
   127→        args: [0, 50],
   128→        msg: 'Messaging limit tier must be less than 50 characters',
   129→      },
   130→    },
   131→  },
   132→  welcome_message_enabled: {
   133→    type: DataTypes.BOOLEAN,
   134→    allowNull: false,
   135→    defaultValue: false,
   136→  },
   137→  welcome_message: {
   138→    type: DataTypes.TEXT,
   139→    allowNull: true,
   140→    validate: {
   141→      len: {
   142→        args: [0, 1000],
   143→        msg: 'Welcome message must be less than 1000 characters',
   144→      },
   145→    },
   146→  },
   147→  auto_reply_enabled: {
   148→    type: DataTypes.BOOLEAN,
   149→    allowNull: false,
   150→    defaultValue: false,
   151→  },
   152→  auto_reply_message: {
   153→    type: DataTypes.TEXT,
   154→    allowNull: true,
   155→    validate: {
   156→      len: {
   157→        args: [0, 1000],
   158→        msg: 'Auto-reply message must be less than 1000 characters',
   159→      },
   160→    },
   161→  },
   162→  business_hours: {
   163→    type: DataTypes.JSON,
   164→    allowNull: true,
   165→    defaultValue: {
   166→      enabled: false,
   167→      timezone: 'UTC',
   168→      schedule: {
   169→        monday: { open: '09:00', close: '18:00', enabled: true },
   170→        tuesday: { open: '09:00', close: '18:00', enabled: true },
   171→        wednesday: { open: '09:00', close: '18:00', enabled: true },
   172→        thursday: { open: '09:00', close: '18:00', enabled: true },
   173→        friday: { open: '09:00', close: '18:00', enabled: true },
   174→        saturday: { open: '09:00', close: '14:00', enabled: false },
   175→        sunday: { open: '09:00', close: '14:00', enabled: false },
   176→      },
   177→    },
   178→  },
   179→  out_of_hours_message: {
   180→    type: DataTypes.TEXT,
   181→    allowNull: true,
   182→    validate: {
   183→      len: {
   184→        args: [0, 1000],
   185→        msg: 'Out of hours message must be less than 1000 characters',
   186→      },
   187→    },
   188→  },
   189→  auto_assignment_enabled: {
   190→    type: DataTypes.BOOLEAN,
   191→    allowNull: false,
   192→    defaultValue: false,
   193→  },
   194→  max_conversations_per_agent: {
   195→    type: DataTypes.INTEGER,
   196→    allowNull: true,
   197→    defaultValue: 10,
   198→    validate: {
   199→      isInt: {
