   325→            user ? 'Agregar' : 'Agregar'
   326→          )}
   327→        </Button>
   328→      </Modal.Footer>
   329→    </>
   330→  );
   331→};
   332→
   333→UserForm.propTypes = {
   334→  user: PropTypes.object,
   335→  onSubmit: PropTypes.func.isRequired,
   336→  onCancel: PropTypes.func.isRequired,
   337→  loading: PropTypes.bool,
   338→  error: PropTypes.string
   339→};
   340→
   341→UserForm.defaultProps = {
   342→  user: null,
   343→  loading: false,
   344→  error: null
   345→};
   346→
   347→export default UserForm;
