     1→/**
     2→ * Line Assignment Modal Component
     3→ *
     4→ * Modal for managing line assignments to users (agents)
     5→ * Phase 5: User Story 3 - Agent User Creation and Line Assignment
     6→ */
     7→
     8→import { useState, useEffect } from 'react';
     9→import { Modal, Form, Button, Alert, Badge, ListGroup, Spinner } from 'react-bootstrap';
    10→import PropTypes from 'prop-types';
    11→import useUsersStore from '../../store/usersStore';
    12→import useLinesStore from '../../store/linesStore';
    13→import './LineAssignmentModal.scss';
    14→
    15→const LineAssignmentModal = ({ show, user, onClose, onSuccess }) => {
    16→  const { assignLinesToUser, loading: userLoading, error } = useUsersStore();
    17→  const { lines, fetchLines, loading: linesLoading } = useLinesStore();
    18→
    19→  const [selectedLineIds, setSelectedLineIds] = useState([]);
    20→
    21→  useEffect(() => {
    22→    if (show) {
    23→      // Fetch available lines
    24→      fetchLines({ is_active: true });
    25→
    26→      // Set currently assigned lines
    27→      if (user && user.assignedLines) {
    28→        setSelectedLineIds(user.assignedLines);
    29→      }
    30→    }
    31→  }, [show, user, fetchLines]);
    32→
    33→  const handleToggleLine = (lineId) => {
    34→    setSelectedLineIds(prev => {
    35→      if (prev.includes(lineId)) {
    36→        return prev.filter(id => id !== lineId);
    37→      } else {
    38→        return [...prev, lineId];
    39→      }
    40→    });
    41→  };
    42→
    43→  const handleSubmit = async (e) => {
    44→    e.preventDefault();
    45→
    46→    try {
    47→      await assignLinesToUser(user.id, selectedLineIds);
    48→      onSuccess();
    49→    } catch (err) {
    50→      console.error('Line assignment error:', err);
    51→    }
    52→  };
    53→
    54→  const handleClose = () => {
    55→    setSelectedLineIds([]);
    56→    onClose();
    57→  };
    58→
    59→  return (
    60→    <Modal
    61→      show={show}
    62→      onHide={handleClose}
    63→      size="lg"
    64→      scrollable
    65→      backdrop="static"
    66→      keyboard={!userLoading}
    67→    >
    68→      <Modal.Header closeButton={!userLoading}>
    69→        <Modal.Title>
    70→          <i className="bi bi-diagram-3 me-2"></i>
    71→          Manage Line Assignments
    72→        </Modal.Title>
    73→      </Modal.Header>
    74→
    75→      <Modal.Body>
    76→        {error && (
    77→          <Alert variant="danger" dismissible>
    78→            {error}
    79→          </Alert>
    80→        )}
    81→
    82→        <div className="mb-3">
    83→          <h6>User: {user?.name}</h6>
    84→          <p className="text-muted mb-0">
    85→            <small>{user?.email}</small>
    86→          </p>
    87→        </div>
    88→
    89→        <Form onSubmit={handleSubmit} id="line-assignment-form">
    90→          <Form.Label className="mb-3">
    91→            <strong>Select WhatsApp Lines to assign:</strong>
    92→          </Form.Label>
    93→
    94→          {linesLoading ? (
    95→            <div className="text-center py-4">
    96→              <Spinner animation="border" variant="primary" />
    97→              <p className="mt-2 text-muted">Loading available lines...</p>
    98→            </div>
    99→          ) : lines.length === 0 ? (
   100→            <Alert variant="info">
   101→              No active WhatsApp lines available. Please create a line first.
   102→            </Alert>
   103→          ) : (
   104→            <ListGroup className="line-assignment-list">
   105→              {lines.map((line) => {
   106→                const isSelected = selectedLineIds.includes(line.id);
   107→                return (
   108→                  <ListGroup.Item
   109→                    key={line.id}
   110→                    action
   111→                    active={isSelected}
   112→                    onClick={() => handleToggleLine(line.id)}
   113→                    className="d-flex justify-content-between align-items-center"
   114→                  >
   115→                    <div>
   116→                      <Form.Check
   117→                        type="checkbox"
   118→                        checked={isSelected}
   119→                        onChange={() => {}} // Handled by ListGroup.Item onClick
   120→                        label={
   121→                          <div>
   122→                            <strong>{line.company_name}</strong>
   123→                            <br />
   124→                            <small className="text-muted">{line.phone_number}</small>
   125→                          </div>
   126→                        }
   127→                        className="mb-0"
   128→                        readOnly
   129→                      />
   130→                    </div>
   131→                    {line.is_active ? (
   132→                      <Badge bg="success">Active</Badge>
   133→                    ) : (
   134→                      <Badge bg="secondary">Inactive</Badge>
   135→                    )}
   136→                  </ListGroup.Item>
   137→                );
   138→              })}
   139→            </ListGroup>
   140→          )}
   141→
   142→          <div className="mt-3">
   143→            <p className="text-muted mb-0">
   144→              <small>
   145→                <i className="bi bi-info-circle me-1"></i>
   146→                Selected: <strong>{selectedLineIds.length}</strong> line(s)
   147→              </small>
   148→            </p>
   149→          </div>
   150→        </Form>
   151→      </Modal.Body>
   152→
   153→      <Modal.Footer>
   154→        <Button
   155→          variant="secondary"
   156→          onClick={handleClose}
   157→          disabled={userLoading}
   158→        >
   159→          Cancel
   160→        </Button>
   161→        <Button
   162→          variant="primary"
   163→          type="submit"
   164→          form="line-assignment-form"
   165→          disabled={userLoading || linesLoading}
   166→        >
   167→          {userLoading ? (
   168→            <>
   169→              <span className="spinner-border spinner-border-sm me-2" />
   170→              Saving...
   171→            </>
   172→          ) : (
   173→            'Save Assignments'
   174→          )}
   175→        </Button>
   176→      </Modal.Footer>
   177→    </Modal>
   178→  );
   179→};
   180→
   181→LineAssignmentModal.propTypes = {
   182→  show: PropTypes.bool.isRequired,
   183→  user: PropTypes.object,
   184→  onClose: PropTypes.func.isRequired,
   185→  onSuccess: PropTypes.func.isRequired
   186→};
   187→
   188→LineAssignmentModal.defaultProps = {
   189→  user: null
   190→};
   191→
   192→export default LineAssignmentModal;
   193→

