     6→
     7→import { useState, useEffect } from 'react';
     8→import { Outlet, NavLink, useNavigate, useLocation } from 'react-router-dom';
     9→import useAuthStore from '../../store/authStore';
    10→import useCompanyStore from '../../store/companyStore';
    11→import authService from '../../services/authService';
    12→import { getSocket, isSocketConnected } from '../../services/socket';
    13→import { setupAssignmentListeners } from '../../services/socket';
    14→import { setupMessageListeners } from '../../services/socketMessageListeners';
    15→import {
    16→  ChatIcon,
    17→  BuildingsIcon,
    18→  PeopleIcon,
    19→  JournalsIcon,
    20→  BoxArrowRightIcon,
    21→  ChevronDownIcon,
    22→  ArrowBarLeftIcon,
    23→  UserIcon,
    24→  FileTextIcon
    25→} from './SidebarIcons';
    26→import './AdminLayout.scss';
    27→
    28→const AdminLayout = () => {
    29→  const navigate = useNavigate();
    30→  const location = useLocation();
    31→  const { user, clearAuth } = useAuthStore();
    32→  const { config, fetchConfiguration } = useCompanyStore();
    33→  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
    34→  const [isChatsExpanded, setIsChatsExpanded] = useState(false);
    35→  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
    36→  const [hoveredSubmenu, setHoveredSubmenu] = useState(null);
    37→  const [popoverPosition, setPopoverPosition] = useState({ top: 0 });
    38→
    39→  const basePath = user?.role === 'admin' ? '/admin' : user?.role === 'manager' ? '/manager' : '/agent';
    40→
    41→  // Fetch company configuration on mount
