    43→    fetchConfiguration();
    44→  }, [fetchConfiguration]);
    45→
    46→  // Setup socket listeners on mount
    47→  useEffect(() => {
    48→
    49→    let cleanupMessages = null;
    50→    let cleanupAssignments = null;
    51→
    52→    // Wait for socket to be ready, then setup listeners
    53→    const setupListeners = () => {
    54→      const socket = getSocket();
    55→
    56→      if (!socket) {
    57→        console.log('[AdminLayout] Socket not available yet, waiting...');
    58→        // Retry after a short delay
    59→        setTimeout(setupListeners, 100);
    60→        return;
    61→      }
    62→
    63→      if (!isSocketConnected()) {
    64→        console.log('[AdminLayout] Socket not connected yet, waiting for connect event...');
    65→        // Wait for connect event
    66→        socket.once('connect', () => {
    67→          console.log('[AdminLayout] Socket connected, setting up listeners');
    68→          cleanupAssignments = setupAssignmentListeners();
    69→          cleanupMessages = setupMessageListeners();
    70→        });
    71→        return;
    72→      }
    73→
    74→      cleanupAssignments = setupAssignmentListeners();
    75→      cleanupMessages = setupMessageListeners();
    76→    };
    77→
    78→    setupListeners();
    79→
    80→    // Cleanup on unmount
    81→    return () => {
    82→      if (cleanupMessages) {
    83→        cleanupMessages();
    84→      }
    85→      if (cleanupAssignments) {
    86→        cleanupAssignments();
    87→      }
    88→    };
    89→  }, []);
    90→
    91→  const handleLogout = async () => {
    92→    try {
    93→      await authService.logout();
