   126→      roles: ['admin', 'agent', 'manager'],
   127→      expanded: isChatsExpanded,
   128→      onClick: toggleChatsMenu,
   129→      items: [
   130→        { to: `${basePath}/chat`, label: 'Todos', roles: ['admin'] },
   131→        { to: `${basePath}/assignments`, label: 'Mis asignaciones', roles: ['admin', 'agent', 'manager'] },
   132→      ]
