   134→    { to: `${basePath}/company`, label: 'Mi empresa', icon: <BuildingsIcon />, roles: ['admin'] },
   135→    { to: `${basePath}/users`, label: 'Usuarios', icon: <PeopleIcon />, roles: ['admin'] },
   136→    { to: `${basePath}/lines`, label: 'Líneas de negocio', icon: <JournalsIcon />, roles: ['admin'] },
