    10→/**
    11→ * Get all users
    12→ *
    13→ * @param {Object} params - Query parameters
    14→ * @param {number} params.page - Page number
    15→ * @param {number} params.limit - Items per page
    16→ * @param {string} params.role - Filter by role (admin or agent)
    17→ * @param {boolean} params.is_active - Filter by active status
    18→ * @returns {Promise<Object>} Users data with pagination
    19→ */
    20→export const getUsers = async (params = {}) => {
    21→  try {
