    40→    throw new Error(error.response?.data?.error || 'Failed to fetch user');
    41→  }
    42→};
    43→
    44→/**
    45→ * Create new user
    46→ *
    47→ * @param {Object} userData - User data
    48→ * @param {string} userData.email - User email
