     1→/**
     2→ * POST /api/v1/users
     3→ *
     4→ * Create new user (admin or agent)
     5→ * Phase 5: User Story 3 - Agent User Creation and Line Assignment
     6→ */
     7→
     8→import { Router } from 'express';
     9→import UserService from '../../../services/UserService.js';
    10→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
    11→import { authorizeRole } from '../../../middleware/authorizeRole.js';
    12→import { AppError } from '../../../middleware/errorHandler.js';
    13→
    14→const router = Router();
    15→
    16→/**
    17→ * @route POST /api/v1/users
    18→ * @desc Create new user
    19→ * @access Admin only
    20→ */
    21→router.post('/', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
    22→  try {
    23→    const { email, password, name, phoneNumber, role } = req.body;
    24→
    25→    // Validation
    26→    if (!email || !password || !name || !role) {
    27→      throw new AppError('Missing required fields: email, password, name, role', 400);
    28→    }
    29→
    30→    if (!['admin', 'agent', 'manager'].includes(role)) {
    31→      throw new AppError('Invalid role. Must be admin, agent, or manager', 400);
    32→    }
    33→
    34→    if (password.length < 8) {
    35→      throw new AppError('Password must be at least 8 characters', 400);
    36→    }
    37→
    38→    // Email validation
    39→    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    40→    if (!emailRegex.test(email)) {
    41→      throw new AppError('Invalid email format', 400);
    42→    }
    43→
    44→    const newUser = await UserService.create({
    45→      email,
    46→      password,
    47→      name,
    48→      phoneNumber,
    49→      role
    50→    });
    51→
    52→    res.status(201).json({
    53→      success: true,
    54→      message: 'User created successfully',
    55→      data: newUser
    56→    });
    57→  } catch (error) {
    58→    next(error);
    59→  }
    60→});
    61→
    62→export default router;
    63→

