     1→/**
     2→ * User Service (Sequelize ORM)
     3→ *
     4→ * Handles user CRUD operations and user management
     5→ * Migrated from raw SQL queries to Sequelize ORM
     6→ * Phase F: Optimized with eager loading and Sequelize transactions
     7→ */
     8→
     9→import bcrypt from 'bcrypt';
    10→import { User, Role, WhatsAppLine, LineUserAssignment } from '../models/sequelize/associations.js';
    11→import sequelize from '../config/sequelize.js';
    12→
    13→class UserService {
    14→  /**
    15→   * Get all users with pagination and filters
    16→   * OPTIMIZED: Eager loading for Role and assigned WhatsAppLines (eliminates N+1 queries)
    17→   */
    18→  async getAll({ page = 1, limit = 20, role, isActive } = {}) {
    19→    try {
    20→      const offset = (page - 1) * limit;
    21→      const where = {};
    22→      const includeWhere = {};
    23→
    24→      if (isActive !== undefined) where.is_active = isActive;
    25→      if (role) includeWhere.role_name = role;
    26→
    27→      const { count, rows: users } = await User.findAndCountAll({
    28→        where,
    29→        include: [
    30→          {
    31→            model: Role,
    32→            as: 'role',
    33→            attributes: ['id', 'role_name'],
    34→            where: Object.keys(includeWhere).length > 0 ? includeWhere : undefined,
    35→            required: Object.keys(includeWhere).length > 0
    36→          },
    37→          {
    38→            model: WhatsAppLine,
    39→            as: 'assignedLines',
    40→            attributes: ['id'],
    41→            through: { attributes: [] },
    42→            required: false
    43→          }
    44→        ],
    45→        attributes: ['id', 'email', 'name', 'phone_number', 'is_active', 'role_id', 'created_at', 'updated_at'],
    46→        limit,
    47→        offset,
    48→        order: [['created_at', 'DESC']],
    49→        distinct: true,
    50→        subQuery: false
    51→      });
    52→
    53→      const usersWithLines = users.map((user) => {
    54→        const userJson = user.toJSON();
    55→        userJson.role = user.role.role_name;
    56→        userJson.assignedLines = user.assignedLines?.map(line => line.id) || [];
    57→        return userJson;
    58→      });
    59→
    60→      return {
    61→        users: usersWithLines,
    62→        total: count,
    63→        page,
    64→        totalPages: Math.ceil(count / limit)
    65→      };
    66→    } catch (error) {
    67→      console.error('Get users error:', error);
    68→      throw error;
    69→    }
    70→  }
    71→
    72→  async getById(userId) {
    73→    try {
    74→      const user = await User.findByPk(userId, {
    75→        include: [
    76→          {
    77→            model: Role,
    78→            as: 'role',
    79→            attributes: ['id', 'role_name']
    80→          },
    81→          {
    82→            model: WhatsAppLine,
    83→            as: 'assignedLines',
    84→            attributes: ['id'],
    85→            through: { attributes: [] },
    86→            required: false
    87→          }
    88→        ],
    89→        attributes: ['id', 'email', 'name', 'phone_number', 'is_active', 'role_id', 'created_at', 'updated_at']
    90→      });
    91→
    92→      if (!user) throw new Error('User not found');
    93→
    94→      const userJson = user.toJSON();
    95→      userJson.role = user.role.role_name;
    96→      userJson.assignedLines = user.assignedLines?.map(line => line.id) || [];
    97→
    98→      return userJson;
    99→    } catch (error) {
   100→      console.error('Get user by ID error:', error);
   101→      throw error;
   102→    }
   103→  }
   104→
   105→  async create({ email, password, name, phoneNumber, role }) {
   106→    try {
   107→      if (!['admin', 'agent', 'manager'].includes(role)) {
   108→        throw new Error('Invalid role');
   109→      }
   110→
   111→      const roleRecord = await Role.findOne({
   112→        where: { role_name: role },
   113→        attributes: ['id']
   114→      });
   115→
   116→      if (!roleRecord) throw new Error('Role not found');
   117→
   118→      const existingUser = await User.findOne({
   119→        where: { email },
   120→        attributes: ['id']
   121→      });
   122→
   123→      if (existingUser) throw new Error('Email already exists');
   124→
   125→      const passwordHash = await bcrypt.hash(password, 12);
   126→      const newUser = await User.create({
   127→        role_id: roleRecord.id,
   128→        email,
   129→        password_hash: passwordHash,
   130→        name,
   131→        phone_number: phoneNumber || null,
   132→        is_active: true
   133→      });
   134→
   135→      return await this.getById(newUser.id);
   136→    } catch (error) {
   137→      console.error('Create user error:', error);
   138→      throw error;
   139→    }
   140→  }
   141→
   142→  async update(userId, updates) {
   143→    try {
   144→      const user = await User.findByPk(userId);
   145→      if (!user) throw new Error('User not found');
   146→
   147→      const allowedFields = ['name', 'phone_number', 'phoneNumber', 'is_active', 'password'];
   148→      const updateData = {};
   149→
   150→      for (const [key, value] of Object.entries(updates)) {
   151→        if (allowedFields.includes(key)) {
   152→          if (key === 'password') {
   153→            updateData.password_hash = await bcrypt.hash(value, 12);
   154→          } else if (key === 'phone_number' || key === 'phoneNumber') {
   155→            updateData.phone_number = value || null;
   156→          } else {
   157→            updateData[key] = value;
   158→          }
   159→        }
   160→      }
   161→
   162→      if (Object.keys(updateData).length === 0) {
   163→        throw new Error('No valid fields to update');
   164→      }
   165→
   166→      await user.update(updateData);
   167→      return await this.getById(userId);
   168→    } catch (error) {
   169→      console.error('Update user error:', error);
   170→      throw error;
   171→    }
   172→  }
   173→
   174→  async delete(userId) {
   175→    try {
   176→      const user = await User.findByPk(userId);
   177→      if (!user) throw new Error('User not found');
   178→
   179→      // Soft delete: mark as inactive instead of hard delete
   180→      // This allows us to provide better error messages on login
   181→      // and maintain data integrity for historical records
   182→      await user.update({ is_active: false });
   183→    } catch (error) {
   184→      console.error('Delete user error:', error);
   185→      throw error;
   186→    }
   187→  }
   188→
   189→  async getAssignedLines(userId) {
   190→    try {
   191→      const user = await User.findByPk(userId, {
   192→        include: [
   193→          {
